import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// One block per "row" (all leading dims flattened), normalizing over the
// last `N` elements which correspond to the normalized_shape.
__global__ void layernorm_kernel(const float* __restrict__ x,
                                 const float* __restrict__ w,
                                 const float* __restrict__ b,
                                 float* __restrict__ y,
                                 int64_t N,
                                 float eps) {
    extern __shared__ float smem[];
    float* s_sum = smem;               // blockDim.x floats
    float* s_sq  = smem + blockDim.x;  // blockDim.x floats

    const int64_t row = blockIdx.x;
    const float* __restrict__ xr = x + row * N;
    float* __restrict__ yr = y + row * N;

    // Accumulate partial sums of x and x^2.
    float sum = 0.0f;
    float sq  = 0.0f;
    for (int64_t i = threadIdx.x; i < N; i += blockDim.x) {
        float v = xr[i];
        sum += v;
        sq  += v * v;
    }
    s_sum[threadIdx.x] = sum;
    s_sq[threadIdx.x]  = sq;
    __syncthreads();

    // Block reduction.
    for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
            s_sq[threadIdx.x]  += s_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    const float mean = s_sum[0] / (float)N;
    float var = s_sq[0] / (float)N - mean * mean;
    var = var < 0.0f ? 0.0f : var;
    const float rstd = rsqrtf(var + eps);

    // Normalize and apply affine transform.
    for (int64_t i = threadIdx.x; i < N; i += blockDim.x) {
        yr[i] = (xr[i] - mean) * rstd * w[i] + b[i];
    }
}

torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor w,
                                torch::Tensor b,
                                double eps,
                                int64_t normalized_size) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda() && b.is_cuda(),
                "All tensors must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto y = torch::empty_like(x);
    const int64_t rows = x.numel() / normalized_size;

    const int threads = 1024;
    const dim3 grid((unsigned int)rows);
    const size_t shmem = 2 * threads * sizeof(float);

    layernorm_kernel<<<grid, threads, shmem,
                       at::cuda::getCurrentCUDAStream()>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        y.data_ptr<float>(),
        normalized_size,
        (float)eps);
    return y;
}
"""

cpp_src = """
torch::Tensor layernorm_forward(torch::Tensor x,
                                torch::Tensor w,
                                torch::Tensor b,
                                double eps,
                                int64_t normalized_size);
"""

_ln_mod = load_inline(
    name="custom_layernorm_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a custom fused CUDA kernel.
    """

    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.normalized_size = 1
        for d in self.normalized_shape:
            self.normalized_size *= d
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        x = x.contiguous().float()
        w = self.weight
        b = self.bias
        if not w.is_cuda:
            w = w.cuda()
            b = b.cuda()
        w = w.contiguous().view(-1)
        b = b.contiguous().view(-1)
        return _ln_mod.layernorm_forward(
            x, w, b, self.eps, self.normalized_size
        )

